import pandas as pd

def clean(df):
    df = df.copy()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # strip whitespace from object columns
    obj_cols = [c for c in df.columns if df[c].dtype == object]
    for c in obj_cols:
        df[c] = df[c].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix known category label variants
    cat_map = {
        'Office Suplies': 'Office Supplies',
        'Accesories': 'Accessories'
    }
    if 'Category' in df.columns:
        df['Category'] = df['Category'].replace(cat_map)
    # ensure numeric types for calculations
    for c in ['Quantity', 'Price', 'Revenue', 'Order_ID']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    return df

def answer(df):
    cdf = clean(df)
    # average unit price = mean of Price per Category
    means = cdf.groupby('Category')['Price'].mean()
    # return plain dict, drop NaN groups
    return {str(k): float(v) for k, v in means.dropna().items()}
